./records/thesis-analyst/2026-07-21/2026-07-21t01-11-54z-bls-cps-employed-people-by-occupation-production-2026-07/draft_stdout.txt:1:{"slug":"cps-production-employment-july-2026","country":"US","type":"data","title":"US production employment, July 2026","question":"What will BLS first report for people employed in production occupations in July 2026, not seasonally adjusted, in millions?","unit":"millions","pointEstimate":7.559,"ciLow":7.368,"ciHigh":7.75,"confidence":0.8,"resolutionDate":"2026-08-06","resolutionSource":"U.S. Bureau of Labor Statistics Employment Situation, Table A-13/A-19","resolutionSourceUrl":"https://www.bls.gov/web/empsit/cpseea19.htm","resolutionRule":"Resolve to the first BLS-published July 2026 total employed value for Production occupations in CPS Employment Situation Table A-13/A-19, not seasonally adjusted, reported in thousands and multiplied by 0.001 to millions. Preserve the first print despite later revisions; round to three decimal places. The registered 2026-08-06 resolutionDate conflicts with the official BLS calendar and June release, which schedule publication for 2026-08-07; the forecast remains tied to the registered target date.","dataPointId":"bls.cps.employed_people_by_occupation.production.july_2026.first_print","historicalContext":[{"label":"January 2026 first print","value":7.905},{"label":"February 2026 first print","value":7.742},{"label":"March 2026 first print","value":7.685},{"label":"April 2026 first print","value":7.883},{"label":"May 2026 first print","value":7.912},{"label":"June 2026 first print","value":7.759},{"label":"July 2025 first print","value":7.662}],"drivers":["Recent CPS production-employment level","Typical July seasonal decline in NSA data","Household-survey sampling volatility","Soft year-over-year production employment"],"sourceContext":["https://www.bls.gov/web/empsit/cpseea19.htm","https://www.bls.gov/news.release/archives/empsit_07022026.pdf","https://www.bls.gov/news.release/archives/empsit_06052026.htm","https://www.bls.gov/news.release/archives/empsit_05082026.htm","https://www.bls.gov/news.release/archives/empsit_08012025.pdf","https://www.bls.gov/schedule/2026/home.htm"],"runAt":"2026-07-21T01:12:14Z","reasoning":[{"kind":"heading","text":"July 2026 CPS production-occupation employment forecast"},{"kind":"text","text":"The target is the first BLS print for total people employed in Production occupations, July 2026, not seasonally adjusted, from CPS Employment Situation Table A-13/A-19. BLS reports thousands; the resolver multiplies by 0.001. Later revisions do not replace the first print."},{"kind":"tool","tool":"official.lookup","call":"Read BLS archived Employment Situation releases for January through March 2026, Table A-13.","result":"Fetched first-print production-occupation employment of 7,905 thousand in January 2026, 7,742 thousand in February, and 7,685 thousand in March."},{"kind":"tool","tool":"official.lookup","call":"Read BLS archived Employment Situation releases for April through June 2026, Table A-13.","result":"Fetched first-print production-occupation employment of 7,883 thousand in April 2026, 7,912 thousand in May, and 7,759 thousand in June."},{"kind":"tool","tool":"official.lookup","call":"Read the archived July 2025 Employment Situation, Table A-13, for a same-month seasonal comparison.","result":"Fetched July production-occupation employment of 7,889 thousand in 2024 and 7,662 thousand in 2025; the June 2025 official table value was 7,938 thousand, implying a 276-thousand June-to-July decline in 2025."},{"kind":"tool","tool":"official.lookup","call":"Verify the July 2026 Employment Situation publication date using the official BLS release calendar and June 2026 release.","result":"The official calendar lists Friday, August 7, 2026 at 8:30 AM ET, and the June release repeats August 7, 2026; this is 1 day after the ledger resolutionDate of August 6."},{"kind":"text","text":"The reference class/base rate is persistence around the